from django.shortcuts import render
from django.template.loader import render_to_string
from .models import LandingContent


def design_system(request):
    components = []
    def add(name, category, usage, code, dependencies='static/app.css · static/ui-foundations.css', preview=None):
        components.append(dict(name=name, category=category, usage=usage, code=code, dependencies=dependencies, preview=preview if preview is not None else code))
    add('Actions & states', 'Controls', 'One primary action per group. Use type="button" outside submission flows. Native disabled prevents activation; keep a visible focus ring.', '<button class="app-button" type="button" data-demo-submit>Send to the team</button> <button class="app-button app-outline" type="button">Save draft</button>')
    add('Labelled input & validation', 'Controls', 'Use the shared form-fields include with a Django form. It renders server errors and help text. Associate additional errors using aria-describedby and aria-invalid.', '<div class="app-form"><label for="sample-title">Title</label><input id="sample-title" aria-invalid="true" aria-describedby="sample-error" value=""><p id="sample-error" class="app-error" role="alert">Give your post a title.</p></div>')
    add('Selection controls', 'Controls', 'Use native selects and checkboxes. Do not replace keyboard interaction with clickable divs.', '<label for="sample-section">Post type</label><select id="sample-section"><option>Article</option><option>Art</option></select><p><label><input type="checkbox"> I have read the contribution guide</label></p>')
    add('Icons & accessible icon buttons', 'Controls', 'Use the shared include. Decorative icons are hidden from assistive technology. Icon-only buttons need an accessible name.', """{% include 'ui/icon.html' with name='auto_stories' %}\n<button class="app-button app-outline" type="button" aria-label="Share profile"><span class="ms-icon" aria-hidden="true">ios_share</span></button>""", 'templates/ui/icon.html · site-fonts.css', '<span class="ms-icon" aria-hidden="true">auto_stories</span><button class="app-button app-outline" type="button" aria-label="Sample share profile"><span class="ms-icon" aria-hidden="true">ios_share</span></button>')
    add('Post labels', 'Cards', 'Reuse existing labels: square category first, rounded supporting tags. Do not redesign the completed post cards.', '<div class="library-card"><div class="library-card-tags"><span>Essay</span><span>English</span></div></div>', 'article-library.css · ui-foundations.css')
    story=LandingContent.objects.filter(is_published=True, section='articles').first()
    if story:
        add('Published post card', 'Cards', 'Pass a published LandingContent as story. Author links and approved images come from the shared template; avoid duplicating credit logic.', "{% load member_tags %}\n{% include 'library-card.html' with story=story %}", 'templates/library-card.html · member_tags · article-library.css', render_to_string('library-card.html', {'story': story}, request=request))
    add('Paper panel & empty state', 'Cards', 'Use the same panel for related sections; an empty state explains the next step.', '<section class="workspace-panel"><h3>Start with an idea.</h3><p>Your published work will appear here.</p><a href="/contribute/">Explore contributions</a></section>')
    add('Draft shelf card', 'Drafts', 'Pass an owned Submission as item to draft-card.html. Private draft links require ownership; never render another member’s draft.', "{% include 'accounts/draft-card.html' with item=item %}", 'templates/accounts/draft-card.html · studio.css', '<article class="draft-card"><div class="draft-art"><span class="draft-paper paper-back"></span><span class="draft-paper paper-front"><span class="ms-icon" aria-hidden="true">menu_book</span></span></div><div class="draft-card-body"><span class="tag-pill">Private draft</span><h3>A thought in progress</h3><p>Only you can see it.</p><button class="app-button app-outline" type="button" disabled>Continue editing (example)</button></div></article>')
    add('Submission status', 'Reviews', 'Use model status choices. Pending revisions leave the approved version live. Include a text label; colour alone is insufficient.', '<div class="composer-status status-pending"><span class="status-dot"></span><strong>Pending review</strong><span>The approved version stays live.</span></div><p><span class="app-pill status-draft">Draft</span> <span class="app-pill status-approved">Approved</span> <span class="app-pill status-declined">Needs changes</span></p>', 'studio.css · app.css')
    add('Review decision', 'Reviews', 'Use review-decision.html with the decision form inside a CSRF-protected POST form. The server enforces permissions and prevents reviewing your own work.', "{% csrf_token %}\n{% include 'accounts/review-decision.html' %}", 'templates/accounts/review-decision.html · accounts.policy · studio.css', '<fieldset class="review-choice"><legend>Example decision</legend><label><input type="radio" name="sample-decision" checked><span><strong>Approve</strong><small>Make this version available.</small></span></label><label><input type="radio" name="sample-decision"><span><strong>Request changes</strong><small>Explain what needs attention.</small></span></label></fieldset>')
    add('Notices & errors', 'Notices', 'Use Django messages for outcomes and role="alert" for errors. Keep guidance close to the action.', '<p class="app-hint" role="status">Draft saved. Only you can see it.</p><div class="app-error" role="alert">Please check the highlighted fields.</div>')
    add('Breadcrumb navigation', 'Navigation', 'Show the current location as text, and previous locations as links. Use actual named Django routes in product templates.', '<nav class="composer-breadcrumb" aria-label="Example breadcrumb"><a href="/dashboard/">Dashboard</a><span aria-hidden="true">/</span><span aria-current="page">Create</span></nav>', 'studio.css · accounts.urls')
    add('Post filters', 'Navigation', 'Keep aria-pressed synchronized with the visible posts. Reuse app.js and data-post-kind; do not hide all posts without an empty state.', '<div class="post-filters" aria-label="Example filters"><button type="button" aria-pressed="true">All</button><button type="button" aria-pressed="false">Articles</button><button type="button" aria-pressed="false">Art</button></div>', 'app.css · app.js · accounts/post-list.html')
    add('Native dialog', 'Dialogs', 'Use dialog.showModal(), a close button, Escape support and focus restoration. The review-image-dialog is the shared image viewer; studio.js owns its data attributes.', '<button class="app-button app-outline" type="button" data-design-dialog-open>Try example dialog</button>\n<dialog class="design-demo-dialog"><h3>A little closer.</h3><p>Example of a keyboard-accessible dialog.</p><button class="app-button" type="button" data-design-dialog-close>Close</button></dialog>', 'Native HTML dialog · design-system.js; product image viewer: accounts/review-dialog.html + studio.js')
    add('Profile portrait', 'Profiles', 'Use approved Profile media through authenticated profile-avatar routes. Pending uploads belong only in the owner/reviewer preview.', "{% include 'accounts/avatar.html' with profile=profile %}", 'templates/accounts/avatar.html · accounts.member_views', render_to_string('accounts/avatar.html', {'profile':request.user.profile}, request=request))
    add('Profile statistics', 'Profiles', 'Counts come from approved credited posts. Private view counts only appear for the owner. Keep the shared rounded strip.', '<div class="profile-stat-strip"><span><strong>0</strong> Articles</span><span><strong>0</strong> Art posts</span></div>')
    add('Scrapbook closing image', 'Profiles', 'Use only approved folio_image. Replacement and removal go through ProfileChange review. Theme selection posts directly to profile-theme and must not be included in approval changes.', """{% if profile.folio_image %}\n<figure class="folio-cutout"><img src="{% url 'profile-folio-image' profile.public_ref %}" alt="Member scrapbook photograph"><figcaption>A little piece of my world.</figcaption></figure>\n{% endif %}""", 'folio.css · ProfileChangeForm · profile-editor.js', '<div class="folio-caption"><p>Stories we share.<br>A place to belong.</p></div>')
    add('Reader controls', 'Reading', 'reader.html and reader.js own pagination, binding, sound and keyboard navigation. Do not mount a second reader or restore the removed text controls. Resize must keep the current passage.', '<footer class="book-controls"><button type="button" aria-label="Previous pages" disabled>Previous</button><output aria-live="polite">Pages 1–2 of 8</output><button type="button">Next</button></footer>', 'templates/reader.html · reader.css · reader.js')
    add('Notebook & writing tools', 'Writing', 'Reuse submission-form.html: studio.js serializes supported plain text, headings, lists and emphasis. Paste is sanitized to plain text. Font and size controls are writer settings, not reader settings.', '<div class="composer-toolbar" role="toolbar" aria-label="Example writing tools"><button type="button">Heading</button><button type="button" aria-label="Example bold"><span class="ms-icon" aria-hidden="true">format_bold</span></button><button type="button">List</button></div><div class="composer-rich-text" data-reading-font="sans" data-reading-size="standard"><p>A thought, on a fresh page.</p><p>Room to find the words.</p></div>', 'templates/accounts/submission-form.html · studio.css · studio.js · ui-foundations.css')
    add('Member-card canvas', 'Profiles', 'Only approved photos, names and actual group/contributor roles feed the card. Visual choices stay on the device and require no profile review. Export and preview share the same canvas drawing.', '<a class="app-button app-outline" href="/me/member-card/">Make my member card <span class="ms-icon" aria-hidden="true">badge</span></a>', 'accounts.experience.member_card · member-card.js · folio.css')
    return render(request, 'design-system.html', {'components': components, 'arc_components': [{'name': 'Dialog', 'source': 'https://uiarc.dev/components/dialog', 'usage': 'Collaboration essay/art previews and submitted-image enlargement.', 'dependencies': 'Radix Dialog, Motion, Lucide', 'accessibility': 'Escape closes; focus is trapped and returned to the trigger.', 'code': '<Dialog open={open} onOpenChange={setOpen}><DialogContent title="Preview" description="Creator permission required.">{content}</DialogContent></Dialog>'}, {'name': 'Select', 'source': 'https://uiarc.dev/components/select', 'usage': 'Profile and collaboration choices; original Django select receives each value.', 'dependencies': 'Radix Select, Motion, Lucide', 'accessibility': 'Labelled trigger, arrow navigation, and native validity forwarding.', 'code': '<Select label="Language" value={value} options={options} onValueChange={syncNativeSelect} />'}, {'name': 'Tabs', 'source': 'https://uiarc.dev/components/tabs', 'usage': 'Related documentation panels within one page.', 'dependencies': 'Radix Tabs, Motion, Lucide', 'accessibility': 'Arrow keys select tabs; panels remain labelled.', 'code': '<Tabs defaultValue="usage"><TabsList aria-label="Example"><TabsTrigger value="usage">Usage</TabsTrigger></TabsList><TabsContent value="usage">Guidance</TabsContent></Tabs>'}, {'name': 'Accordion', 'source': 'https://uiarc.dev/components/accordion', 'usage': 'Secondary review differences. Important decisions remain outside.', 'dependencies': 'Radix Accordion, Motion, Lucide', 'accessibility': 'Labelled heading and expanded state; collapsed content is hidden.', 'code': '<Accordion defaultOpen={-1} items={[{title:"Changed sections",content:summary}]} />'}, {'name': 'Verification code', 'source': 'https://uiarc.dev/components/blocks/otp-input', 'usage': 'Signup, account email and numeric recovery codes; never backup codes.', 'dependencies': 'Motion', 'accessibility': 'Paste, one-time-code autofill, labelled digits and validation focus.', 'code': '<OtpInput label="Six-digit verification code" value={value} onChange={syncNativeCode} />'}, {'name': 'File dropzone', 'source': 'https://uiarc.dev/components/file-dropzone', 'usage': 'Profile, collaboration reference and consent files. Server rules remain authoritative.', 'dependencies': 'Motion, Lucide', 'accessibility': 'Choose/drop, thumbnail, filename, replacement and labelled removal.', 'code': '<FileDropzone multiple={false} maxFiles={1} onFilesChange={syncNativeFiles} />'}, {'name': 'Button', 'source': 'https://uiarc.dev/components/button', 'usage': 'Plain form submissions with honest busy states.', 'dependencies': 'Motion', 'accessibility': 'Native button; validation runs before busy feedback.', 'code': '<Button loading={busy} onClick={() => form.requestSubmit(originalButton)}>Save and send for review</Button>'}, {'name': 'Copy button', 'source': 'https://uiarc.dev/components/copy-button', 'usage': 'Copy contributor code with success/failure announcements.', 'dependencies': 'Motion, Lucide', 'accessibility': 'Labelled button and polite result announcement.', 'code': '<CopyButton value={code} label="Copy code" />'}, {'name': 'Code block', 'source': 'https://uiarc.dev/components/code-block', 'usage': 'Contributor examples, source highlighting and copy access.', 'dependencies': 'Motion, Lucide, CopyButton', 'accessibility': 'Scrollable source, named copy action and expansion.', 'code': '<CodeBlock code={code} language="html" maxLines={12} />'}, {'name': 'Tooltip', 'source': 'https://uiarc.dev/components/tooltip', 'usage': 'Supplementary labels for notebook icon controls.', 'dependencies': 'Radix Tooltip, Motion', 'accessibility': 'Existing buttons keep their accessible names and handlers.', 'code': '<Tooltip content="Bold"><button aria-label="Bold">B</button></Tooltip>'}, {'name': 'Empty state', 'source': 'https://uiarc.dev/components/empty-state', 'usage': 'Empty collaborations, drafts and search results. Existing actions are retained.', 'dependencies': 'Motion, Lucide', 'accessibility': 'Named region, heading and existing next-step links.', 'code': '<EmptyState title="A fresh page awaits." description="Start an idea." action={existingAction} />'}]})
